// Generated by scripts/generate-app-kits.mjs from packages/runtime/kits/figures/<id>.webp. Do not edit: change those
// files, then run npm run generate:app-kits.

/** Each figure's id and its picture as a data: URL, one a line. */
const FIGURES = `acorn data:image/webp;base64,
bolt data:image/webp;base64,
cloud data:image/webp;base64,
crown data:image/webp;base64,
flame data:image/webp;base64,
heart data:image/webp;base64,
moon data:image/webp;base64,
mushroom data:image/webp;base64,
planet data:image/webp;base64,
puzzle data:image/webp;base64,
rocket data:image/webp;base64,
star data:image/webp;base64,`;

/** Each agent figure a kit's page may show, by its id, as a data: URL (kitPage puts the ones its data names in). */
export const KIT_FIGURES: Readonly<Record<string, string>> = Object.freeze(
	Object.fromEntries(
		FIGURES.split("\n").map((line) => [line.slice(0, line.indexOf(" ")), line.slice(line.indexOf(" ") + 1)]),
	),
);
